INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K01','יסודות','{"id":"META-K01","category":"יסודות","content":"מנהל המודעות הוא הכלי לניהול מודעות ולבחינת תוצאות. נבחר מטרה, מיקום המרה ומדד ביצוע בהתאם לצורך העסקי.","tags":["מנהל המודעות","Ads Manager"],"conditions":["ANY"],"source":"https://www.facebookblueprint.com/student/path/219699-selecting-objectives-course","source_status":"verified_course_overview"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K02','נכסים','{"id":"META-K02","category":"נכסים","content":"חשבון מודעות הוא הנכס שבו מנוהלים קמפיינים ונתוני הפרסום. בחירת חשבון במערכת תתאפשר רק מתוך הרשימה שהשרת אימת עבור הלקוח.","tags":["חשבון מודעות","בחירת חשבון"],"conditions":["ANY"],"source":"https://developers.facebook.com/docs/marketing-api/overview/authorization/","source_status":"reference_unavailable; app_control_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K03','נכסים','{"id":"META-K03","category":"נכסים","content":"פורטפוליו עסקי מרכז נכסים עסקיים והרשאות. הוא אינו זהה לחשבון מודעות יחיד. אין צורך לבקש סיסמה או להעביר בעלות כדי להתחיל בבדיקת החיבור.","tags":["פורטפוליו","Business Portfolio","Business Manager"],"conditions":["ANY"],"source":"https://www.facebook.com/business/help/1710077379203657","source_status":"reference_requires_current_dashboard_verification"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K04','נכסים','{"id":"META-K04","category":"נכסים","content":"דף Facebook וחשבון Instagram משמשים זהויות ונכסים לתוכן. חשבון מודעות משמש לניהול הפרסום. חיבור של אחד אינו הוכחה לגישה לאחרים.","tags":["דף","אינסטגרם","הבדל"],"conditions":["ANY"],"source":"https://developers.facebook.com/docs/marketing-api/","source_status":"reference_requires_current_dashboard_verification"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K05','הרשאות','{"id":"META-K05","category":"הרשאות","content":"במערכת זו קריאת נתוני פרסום דורשת ads_read. פעולות ניהול דורשות הרשאה מתאימה וגם מנגנון אישור וכתיבה פתוח; הרשאת קריאה לבדה אינה מאפשרת שינוי קמפיין.","tags":["הרשאות","ads_read","ads_management"],"conditions":["ANY"],"source":"metaConnection.js; approvalPolicy.js; metaWrite.js","source_status":"application_contract_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K06','חיבור','{"id":"META-K06","category":"חיבור","content":"החיבור נעשה דרך מסך Meta הרשמי ובהגדרות האפליקציה הקיימות. אין לשלוח סיסמה, קוד אימות או אסימון גישה בהודעת WhatsApp.","tags":["Facebook Login for Business","התחברות"],"conditions":["NOT_CONNECTED","CONNECTION_OFFERED","RECONNECT_REQUIRED"],"source":"https://developers.facebook.com/docs/facebook-login/facebook-login-for-business/","source_status":"reference_unavailable_429; app_flow_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K07','חיבור','{"id":"META-K07","category":"חיבור","content":"קישור החיבור אישי וקצר תוקף. השרת בודק state וקשירת דפדפן לפני שמירת חיבור מוצפן. הודעה כמו ״התחברתי״ מפעילה בדיקה ואינה הוכחת חיבור.","tags":["OAuth","קישור","state","התחברתי"],"conditions":["ANY"],"source":"metaConnection.js; metaOAuth.js","source_status":"application_contract_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K08','בחירה','{"id":"META-K08","category":"בחירה","content":"אם קיימים כמה חשבונות זמינים, מוצגת רשימת חשבונות מורשים לבחירה. שם או מזהה שנכתבו בצ׳אט נבדקים שוב בשרת לפני שיוך החשבון.","tags":["כמה חשבונות","בחירה"],"conditions":["ACCOUNT_SELECTION_REQUIRED","CONNECTED"],"source":"metaConnection.js: accounts/selectAccount","source_status":"application_contract_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K09','התאוששות','{"id":"META-K09","category":"התאוששות","content":"אם אין חשבון מודעות, אפשר להכין טיוטת אסטרטגיה ומודעות מקומית. יצירת נכס ב-Meta היא פעולה נפרדת לבעל העסק; הבוט אינו יוצר הרשאות או בעלות בשמו.","tags":["אין חשבון","חדש"],"conditions":["NOT_CONNECTED","ACCOUNT_SELECTION_REQUIRED"],"source":"campaignJourney.js; metaConversation.js","source_status":"application_policy"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K10','התאוששות','{"id":"META-K10","category":"התאוששות","content":"כשחסרה הרשאה, נציין איזו פעולה נחסמה ומה נדרש לבדוק בחשבון. שינוי הרשאות מתבצע ב-Meta על ידי בעל הרשאה, והמערכת לא תטען שההרשאה הוענקה לפני אימות.","tags":["אין הרשאה","חסרה הרשאה"],"conditions":["MISSING_PERMISSIONS","CONNECTION_FAILED"],"source":"https://developers.facebook.com/docs/marketing-api/overview/authorization/","source_status":"reference_unavailable; application_policy"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K11','התאוששות','{"id":"META-K11","category":"התאוששות","content":"תוקף ההרשאה נקבע לפי הנתון שהתקבל מהשרת. כשאין הרשאה תקפה נבקש חיבור מחדש; לא נבטיח תוקף קבוע או טוקן שלא פג.","tags":["פג תוקף","Token","הרשאה פגה"],"conditions":["TOKEN_EXPIRED","RECONNECT_REQUIRED"],"source":"https://developers.facebook.com/docs/facebook-login/guides/access-tokens/","source_status":"reference_unavailable_429; expiry_checked_in_backend"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K12','ניהול חיבור','{"id":"META-K12","category":"ניהול חיבור","content":"אפשר לבקש לחדש או לנתק את החיבור. ניתוק מוחק את נתוני החיבור המקומיים ומבטל אישורים ממתינים; הסרה מלאה של הרשאת האפליקציה ניתנת לבדיקה גם בהגדרות Meta.","tags":["חידוש","ניתוק","לנתק"],"conditions":["ANY"],"source":"metaConnection.js: renew/disconnect","source_status":"application_contract_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K13','תשלום','{"id":"META-K13","category":"תשלום","content":"תקציב המדיה ודמי הניהול הם רכיבים נפרדים. הצעת ניהול במתנה אינה אומרת שהחשיפות ב-Meta בחינם. תנאי המימון והתשלום צריכים להיקבע במפורש לפני פרסום.","tags":["תשלום","מי משלם","תקציב","מתנה"],"conditions":["ANY"],"source":"application business policy; campaignJourney.js","source_status":"application_policy_not_financial_advice"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K14','טיוטה','{"id":"META-K14","category":"טיוטה","content":"אפשר להכין טיוטה מקומית בלי חשבון מחובר. יצירת קמפיין ממשי דורשת חשבון מאומת, הרשאות ואישור תוכנית מדויקת; אם היא מותרת, מצב ההתחלה הוא PAUSED.","tags":["טיוטה","PAUSED","קמפיין"],"conditions":["ANY"],"source":"campaignWorkflows.js; approvalPolicy.js; metaWrite.js","source_status":"application_contract_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
INSERT INTO meta_ads_knowledge(id,category,payload,version,updated_at) VALUES('META-K15','אישורים','{"id":"META-K15","category":"אישורים","content":"אישור אסטרטגיה, אישור יצירת קמפיין ואישור הפעלתו הם שלבים נפרדים. ״כן״ לשיחה אינו הרשאה להוציא כסף. פעולות בחשבון ממשיכות לעבור את מנגנון האישור הקיים.","tags":["אישור","הפעלה","תקציב"],"conditions":["ANY"],"source":"approvalEngine.js; approvalPolicy.js; lifecycleApprovalService.js","source_status":"application_contract_verified_by_tests"}'::jsonb,1,'2026-10-26') ON CONFLICT(id) DO UPDATE SET category=EXCLUDED.category,payload=EXCLUDED.payload,version=EXCLUDED.version,updated_at=EXCLUDED.updated_at WHERE meta_ads_knowledge.version<EXCLUDED.version;
